using System.IO;
using System.Text.Json;
namespace FaceAssets;
// Bounds are parser budgets; they do not describe a particular race or mesh.
public static class JslotSchema {
 public static void Validate(JsonElement root){
  if(root.TryGetProperty("mods",out var mods)){if(mods.ValueKind!=JsonValueKind.Array||mods.GetArrayLength()>8192)throw new InvalidDataException("Invalid saved mod table");var indexes=new HashSet<uint>();foreach(var m in mods.EnumerateArray()){uint index=m.GetProperty("index").GetUInt32();string name=m.GetProperty("name").GetString()??"";if(!indexes.Add(index)||Path.GetFileName(name)!=name||name.Length>260)throw new InvalidDataException("Ambiguous/unsafe saved mod table");}}
  if(!root.TryGetProperty("morphs",out var morphs))return;if(morphs.ValueKind!=JsonValueKind.Object)throw new InvalidDataException("Invalid morph object");
  if(morphs.TryGetProperty("default",out var d)){if(d.ValueKind!=JsonValueKind.Object)throw new InvalidDataException("Invalid default morph object");foreach(var (name,limit) in new[]{("morphs",19),("presets",4)})if(d.TryGetProperty(name,out var list)){if(list.ValueKind!=JsonValueKind.Array||list.GetArrayLength()>limit)throw new InvalidDataException("Invalid engine morph array");foreach(var item in list.EnumerateArray()){double value=item.GetDouble();if(!double.IsFinite(value)||name=="presets"&&(value<0||value>uint.MaxValue||value!=Math.Truncate(value)))throw new InvalidDataException("Invalid engine morph number");}}}
  if(morphs.TryGetProperty("custom",out var custom)){if(custom.ValueKind!=JsonValueKind.Array||custom.GetArrayLength()>2048)throw new InvalidDataException("Invalid custom morph array");foreach(var item in custom.EnumerateArray())if(!double.IsFinite(item.GetProperty("value").GetDouble()))throw new InvalidDataException("Invalid custom morph value");}
  if(morphs.TryGetProperty("sculpt",out var hosts)){if(hosts.ValueKind!=JsonValueKind.Array||hosts.GetArrayLength()>128)throw new InvalidDataException("Invalid Sculpt hosts");double divisor=morphs.TryGetProperty("sculptDivisor",out var scale)?scale.GetDouble():10000;if(!double.IsFinite(divisor)||divisor<=0)throw new InvalidDataException("Invalid Sculpt scale");long total=0;foreach(var host in hosts.EnumerateArray()){BsaArchive.Normalize(host.GetProperty("host").GetString()??"");int vertices=host.GetProperty("vertices").GetInt32();var data=host.GetProperty("data");if(vertices<0||vertices>200000||data.ValueKind!=JsonValueKind.Array||data.GetArrayLength()>vertices||(total+=data.GetArrayLength())>1000000)throw new InvalidDataException("Sculpt size budget");var indexes=new HashSet<int>();foreach(var row in data.EnumerateArray()){if(row.ValueKind!=JsonValueKind.Array||row.GetArrayLength()!=4)throw new InvalidDataException("Invalid Sculpt row");int i=row[0].GetInt32();if(i<0||i>=vertices||!indexes.Add(i))throw new InvalidDataException("Invalid/duplicate Sculpt index");for(int c=1;c<4;c++){double value=row[c].GetDouble()/divisor;if(!double.IsFinite(value)||Math.Abs(value)>1000)throw new InvalidDataException("Invalid Sculpt delta");}}}}
 }
}
